def _prepare(dataset):
    (train, test) = (dataset['train'], dataset['test'])
    features = _aligned_features(train, test)
    n_train = len(train['lab_id'])
    cal = _stress_calibration(dataset['calibration_load_cells'])
    return tuple(((group['past_channel_raw'] @ cal[:-1] + cal[-1], group['hold_channel_raw'] @ cal[:-1] + cal[-1], x) for (group, x) in ((train, features[:n_train]), (test, features[n_train:]))))

def _design(taus, dt, times, coupon):
    (past, hold, x) = coupon
    z = np.zeros((len(hold), 2))
    for (alpha, stress) in zip(-np.expm1(-dt[:, None] / taus), past.T):
        z += alpha * (stress[:, None] - z)
    gap = hold[:, None] - z
    growth = -np.expm1(-times[:, None] / taus)
    curve = np.concatenate((gap[:, None, :] * growth, times[None, :, None] * x[:, None, :]), axis=2)
    rate = np.column_stack((gap / taus, x))
    return (curve, rate)

def _fit(dt, times, coupon, curve_obs, rate_obs, *, adaptive=True):
    from scipy.optimize import least_squares
    y = np.concatenate((curve_obs.ravel(), rate_obs))
    k = curve_obs.size
    (low, high) = np.log([0.0500001, 24.999999])
    bounds = ([low, low] + [-np.inf] * 7, [high, high] + [np.inf] * 7)

    def design(log_tau):
        (curve, rate) = _design(np.exp(log_tau), dt, times, coupon)
        return np.vstack((curve.reshape(-1, 7), rate))

    def residual(p):
        return design(p[:2]) @ p[2:] - y

    def fit(p, loss, scale):
        return least_squares(lambda a: residual(a) / scale, p, bounds=bounds, x_scale='jac', loss=loss, max_nfev=250)
    initial_scale = max(0.02 * np.median(np.abs(y)), 1e-07)
    fits = []
    for start in ((0.25, 2.0), (0.7, 5.0), (1.3, 14.0)):
        lt = np.log(start)
        beta = np.linalg.lstsq(design(lt), y, rcond=None)[0]
        fits.append(fit(np.r_[lt, beta], 'soft_l1', initial_scale))
    best = min(fits, key=lambda result: result.cost).x
    if adaptive:
        e = residual(best)
        scales = [max(1.4826 * np.median(np.abs(r - np.median(r))), initial_scale * 0.002) for r in (e[:k], e[k:])]
        scale = 2.5 * np.repeat(scales, [k, len(rate_obs)])
        best = fit(best, 'cauchy', scale).x
    order = np.argsort(best[:2])
    return (np.exp(best[:2][order]), np.r_[best[2:4][order], best[4:]])

def design(x, mode):
    from itertools import combinations_with_replacement
    a = [np.ones(len(x)), x]
    if mode in ('diag2', 'diag23', 'full2', 'full23'):
        a += [x * x]
    if mode in ('diag3', 'diag23', 'full23'):
        a += [x * x * x]
    if mode in ('full2', 'full23'):
        a += [np.column_stack([x[:, i] * x[:, j] for i in range(4) for j in range(i + 1, 4)])]
    if mode == 'full23':
        a += [np.column_stack([np.prod(x[:, ix], axis=1) for ix in combinations_with_replacement(range(4), 3) if len(set(ix)) > 1])]
    return np.column_stack(a)

def fit(a, y):
    keep = np.ones(len(a), bool)
    for step in range(6):
        coef = np.linalg.lstsq(a[keep], y[keep], rcond=None)[0]
        e = np.linalg.norm(a @ coef - y, axis=1)
        new = e < max(0.001, 5 * np.median(e))
        if np.array_equal(new, keep) or new.sum() < a.shape[1]:
            break
        keep = new
    return coef

def terms(z, degree, full):
    from itertools import combinations_with_replacement
    return np.column_stack([np.ones(len(z))] + [np.prod(z[:, ix], axis=1) for j in range(1, degree + 1) for ix in combinations_with_replacement(range(4), j) if full or len(set(ix)) == 1])
